class SyslogException(Exception):
    """A base exception class for the ute_syslog package."""


class ParsingError(SyslogException):
    """Raised when regexp cannot match any string in syslog."""


class InvalidDestinationError(SyslogException):
    """Exception raised if destination and unzip flag combination is incorrect"""


class WrongResponseError(SyslogException):
    """Exception raised when response from the execute command is unexpected."""

    def __init__(self, msg, ssh_out, ssh_rc, e):
        output_msg = f"+++ Output +++\n{ssh_out}\n\n"
        rc_msg = f"+++ Return Code +++\n{ssh_rc}\n\n"
        error_msg = f"+++ Error +++\n{e}\n\n"
        msg = f"{msg}\n" + output_msg + rc_msg + error_msg


class IpAndPortBindingError(SyslogException):
    """Exception raised if ip and port is already being used by other application."""


class InvalidRequestedAddressError(SyslogException):
    """Exception raised if IP is missing."""


class SyslogInitializationError(SyslogException):
    """Exception raised if syslog does not start successfully."""


class StopSyslogError(SyslogException):
    """Exception raised if syslog process cannot be killed in time."""


class ExhaustedNumberOfAttemptsError(SyslogException):
    """Exception raised when connection failed for a given number of attempts"""


class FileCollectorError(Exception):
    """Exception raised if it was not possible to collect files."""


class ConnectionNotSetUpError(SyslogException):
    """Exception raised when start method is called before SSH connection is made"""


class ConnectionAlreadySetUpError(SyslogException):
    """Raised when user tries to set up new SSH connection while another one is already present"""


class SyslogCLINotFoundError(SyslogException):
    """Raised when our SSH Client cannot find cli_syslog in PATH"""
